import numpy as np
import torch

class MyPreprocessor:
    def __init__(self):
        self.eps = None

    def _raw_reshape(self, data):
        return data

    def make_loader_cfg(self):
        return {"batch_size": 1, "num_workers": 0}

    def fit(self, events):
        dists = []
        max_events = min(len(events), 200)
        for i, evt in enumerate(events):
            if i >= max_events:
                break
            r = evt["hit_r"]
            theta = evt["hit_theta"]
            z = evt["hit_z"]
            track_id = evt["track_id"]
            x = r * np.cos(theta)
            y = r * np.sin(theta)
            for t in np.unique(track_id):
                idx = np.where(track_id == t)[0]
                if idx.shape[0] <= 1:
                    continue
                layer_id = evt["layer_id"][idx]
                order = np.argsort(layer_id)
                pts = np.stack([x[idx][order], y[idx][order], z[idx][order]], axis=1)  # [n_hits_t,3]
                diffs = pts[1:] - pts[:-1]  # [n_hits_t-1,3]
                d = np.linalg.norm(diffs, axis=1)  # [n_hits_t-1]
                dists.extend(d.tolist())
        if len(dists) == 0:
            self.eps = 1.0
        else:
            arr = np.array(dists, dtype=float)
            self.eps = float(np.percentile(arr, 90)) * 1.1
        global PREPROC
        PREPROC = self
        return self

    def transform(self, data):
        r = data[:, 0]            # [N]
        theta = data[:, 1]        # [N]
        z = data[:, 2]            # [N]
        x = r * torch.cos(theta)  # [N]
        y = r * torch.sin(theta)  # [N]
        coords = torch.stack((x, y, z), dim=1)  # [N,3]
        return coords

def make_preprocessor():
    return MyPreprocessor()

class HitClassifier(torch.nn.Module):
    def __init__(self, in_features):
        super().__init__()
        self.eps = getattr(PREPROC, "eps", 1.0)

    def forward(self, data):
        if isinstance(data, torch.Tensor):
            coords = data.cpu().detach().numpy()  # [N,3]
        else:
            coords = np.array(data)               # [N,3]
        N = coords.shape[0]
        labels_np = np.full(N, -1, dtype=int)
        centers = []
        for i in range(N):
            pt = coords[i]
            if not centers:
                centers.append(pt.copy())
                labels_np[i] = 0
            else:
                centers_arr = np.vstack(centers)               # [K,3]
                dists = np.linalg.norm(centers_arr - pt[None, :], axis=1)  # [K]
                j = int(np.argmin(dists))
                if dists[j] <= self.eps:
                    labels_np[i] = j
                    centers[j] = 0.9 * centers[j] + 0.1 * pt
                else:
                    labels_np[i] = len(centers)
                    centers.append(pt.copy())
        labels = torch.from_numpy(labels_np).long()
        try:
            return labels.to(data.device)
        except:
            return labels

def make_model(in_features):
    return HitClassifier(in_features)

